document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.hasAttribute('data-cash-add'))openCashTransfer();if(b.dataset.cashEdit)openCashTransfer(b.dataset.cashEdit);if(b.dataset.cashDelete)run(async()=>{const next=structuredClone(plan);next.settings.cashTransfers=next.settings.cashTransfers.filter(t=>t.id!==b.dataset.cashDelete);await save(next);render();});});

document.addEventListener('change',e=>{if(e.target.id==='projection-chart-year'){projectionChartYear=Number(e.target.value);$('projection-dashboard').outerHTML=projectionCharts(projection?.rows||[],plan.settings,money,projectionChartYear);$('projection-chart-year').focus();}});

function familyCreditResults(){
 const s=plan.settings,r=projection?.rows?.[0];if(!s.includeChildCredit&&!s.includeEarnedCredit)return '<p class="help">Credits are off. Existing plans keep their previous results until you enable them.</p>';
 if(!r)return '<p>Resolve projection errors to estimate credits.</p>';
 return `<h3>${r.year} estimate</h3><p>Child tax credit: <strong>${money(r.childTaxCredit)}</strong> · Refundable additional child credit: <strong>${money(r.additionalChildTaxCredit)}</strong> · Earned income credit: <strong>${money(r.earnedIncomeCredit)}</strong></p>${r.creditNotes.map(t=>`<p class="note warning">${esc(t)}</p>`).join('')}<p class="help">See Yearly projection → Taxes for every year. Refundable credits also appear as household cash in the income graphs and cash flow. Refunds are assigned to the tax year for planning; actual receipt is generally later.</p>`;
}
function familyCreditView(){
 const s=plan.settings,yesNo=[[false,'No'],[true,'Yes']],enabled=s.includeChildCredit||s.includeEarnedCredit;
 return `<section class="card" id="family-credit-section"><h2>Children &amp; family tax credits</h2><form id="family-credit-form"><div class="form-grid">${field('includeChildCredit','Include child tax credit',s.includeChildCredit===true,'text',yesNo)}${field('includeEarnedCredit','Include earned income credit',s.includeEarnedCredit===true,'text',yesNo)}</div><div id="family-credit-options" ${enabled?'':'hidden'}><p>Enter each child's age on December 31 of the plan start year. Ages advance automatically. Child tax credit needs eligible children; EITC can apply without children.</p><div class="form-grid">${field('ctcEligible','Child credit: taxpayer eligibility confirmed',s.ctcEligible===true,'text',yesNo)}${field('eitcEligible','EITC: household eligibility confirmed',s.eitcEligible===true,'text',yesNo)}${field('eitcSeparatedEligible','Separate filing: EITC separated-spouse exception applies',s.eitcSeparatedEligible===true,'text',yesNo)}${field('eitcOtherInvestmentIncome','Other EITC investment income ($ / year)',s.eitcOtherInvestmentIncome||0)}${field('familyCreditMagiAdjustment','Credit AGI / MAGI adjustment ($ / year)',s.familyCreditMagiAdjustment||0)}</div><details><summary>What am I confirming?</summary><p><strong>Child credit:</strong> you meet taxpayer identification requirements and are eligible to claim the credit. For a joint return, at least one spouse has the required valid SSN and the other has a timely SSN or ITIN. Confirm each child's separate dependency, relationship, residency, support, citizenship and valid-SSN rules in the child editor.</p><p><strong>EITC:</strong> you and a joint-filing spouse have valid SSNs, meet citizenship/residency rules, are not disqualified as another person's qualifying child/dependent, have no credit ban, and do not file Form 2555. Confirm the U.S. home requirement for childless EITC and each child's eligibility separately. For separate filing, confirm the IRS separated-spouse exception only if applicable; a qualifying child is also required.</p><p>Salaries less pre-tax workplace contributions supply earned income. Pensions, Social Security and conversions are not earned income. Modeled taxable-account dividends, realized gains and taxable/tax-exempt bond interest count toward the investment-income limit. Add only investment income not already modeled (including interest embedded in manual account returns); this field affects eligibility only, so enter the actual income in Income as well if needed. AGI/MAGI adjustment affects credit phaseouts only. These adjustments stay fixed each year.</p><p>Employee-wage estimates only. Self-employment, combat pay, foreign-income, Puerto Rico special rules, state credits and other-dependent credits are not modeled. Do not enter modeled family credits again under manual federal credits. Eligibility confirmations persist across years through each child's last included year; review them when circumstances change. No Social Security numbers are collected.</p><a href="https://www.irs.gov/credits-deductions/individuals/child-tax-credit" target="_blank" rel="noopener">IRS child tax credit rules</a> · <a href="https://www.irs.gov/publications/p596" target="_blank" rel="noopener">IRS earned income credit rules</a></details><div class="card-head"><h3>Children</h3><button type="button" data-child-add>+ Add child</button></div><div class="table-scroll"><table><thead><tr><th>Child label</th><th>Age in ${s.startYear}</th><th>Last included year</th><th>Child credit eligible</th><th>EITC eligible</th><th>Actions</th></tr></thead><tbody>${(s.creditChildren||[]).map(c=>`<tr><td>${esc(c.name)}</td><td>${c.age}</td><td>${c.lastYear}</td><td>${c.ctcEligible?'Yes':'No'}</td><td>${c.eitcEligible?'Yes':'No'}</td><td><button type="button" class="secondary" data-child-edit="${esc(c.id)}">Edit</button> <button type="button" class="secondary" data-child-remove="${esc(c.id)}">Remove</button></td></tr>`).join('')||'<tr><td colspan="6">No children entered. Add a child for child-based credits; leave empty for childless EITC.</td></tr>'}</tbody></table></div><p class="help">Amounts, ages, income limits and phaseout rates come from the annual retirement tax file (${annual.retirement.year}). Credit maxima and EITC dollar limits use plan inflation for future years; child-credit phaseout thresholds and earned-income floor stay fixed. EITC is a continuous formula estimate, so it can differ from the IRS tax-table amount.</p></div></form><div id="family-credit-results" aria-live="polite">${familyCreditResults()}</div></section>`;
}
function openChild(id){
 const value=structuredClone((plan.settings.creditChildren||[]).find(c=>c.id===id)||{id:crypto.randomUUID(),name:'Child '+((plan.settings.creditChildren||[]).length+1),age:0,lastYear:plan.settings.startYear+plan.settings.years-1,studentThroughAge:0,disabled:false,ctcEligible:false,eitcEligible:false});
 editorState={kind:'child',value};$('editor-title').textContent=id?'Edit child':'Add child';$('editor-error').textContent='';
 const yesNo=[[false,'No'],[true,'Yes']];
 $('editor-fields').innerHTML=field('name','Child label (name optional)',value.name,'text')+field('age','Age on Dec 31 of '+plan.settings.startYear,value.age)+field('lastYear','Last year eligibility assumptions apply',value.lastYear)+field('ctcEligible','Child tax credit: non-age requirements met',value.ctcEligible,'text',yesNo)+field('eitcEligible','EITC: non-age requirements met',value.eitcEligible,'text',yesNo)+field('studentThroughAge','Full-time student through age (0 = none planned)',value.studentThroughAge)+field('disabled','Permanently and totally disabled for EITC age exception',value.disabled,'text',yesNo)+'<p class="help full">Child credit confirmation includes qualifying relationship, dependency claim, over-half-year residency (or valid exception), not providing over half their own support, citizenship/residency and valid SSN. EITC confirmation includes qualifying relationship, U.S. residence over half the year, valid SSN, joint-return test and any competing-claim tiebreaker. The credits have different rules; confirm each separately. Ages are checked automatically. For EITC ages 19–23, student status means full-time for at least five months of each year through the entered age. Disability bypasses the EITC age/student test only; it does not extend the child tax credit age. Last included year allows residency/claim assumptions to end earlier.</p>';
 $('editor-fields').innerHTML=$('editor-fields').innerHTML.replaceAll('field-','child-field-');
 if(!id)$('child-field-age').value='';
 $('editor').showModal();
}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;
 if(b.hasAttribute('data-child-add'))openChild();
 if(b.dataset.childEdit)openChild(b.dataset.childEdit);
 if(b.dataset.childRemove)run(async()=>{if(!confirm('Remove this child from the plan credit estimates?'))return;const next=structuredClone(plan);next.settings.creditChildren=next.settings.creditChildren.filter(c=>c.id!==b.dataset.childRemove);await save(next);render();});
});

function openBalanceUpdate(id){
 const a=plan.accounts.find(a=>a.id===id);if(!a)return;
 const value={accountId:id,date:localDate(),amount:accountTotal(plan,a),note:'',apply:a.mode==='balance'};
 editorState={kind:'balanceUpdate',value};$('editor-title').textContent='Update balance · '+a.name;$('editor-error').textContent='';
 $('editor-fields').innerHTML=field('date','Balance as-of date',value.date,'date')+field('amount','Account balance ($)',value.amount)+field('apply','How to use this balance',value.apply,'text',[[true,a.mode==='holdings'?'Update plan — switch to entered total':'Update plan starting balance and save history'],[false,'History only — keep current projection balance']])+field('note','Note (optional)',value.note,'text')+`<p class="help full">Current modeled value: ${money(value.amount)}. Enter the full account value, including any bonds already included in its total. A market gain or loss changes market value, not taxable cost basis. Use Edit if a deposit, withdrawal or sale also changes cost basis.</p><p class="note full">${a.mode==='holdings'?'This account is calculated from holdings. History only keeps that method. Choosing Update plan switches to an entered total: holdings remain as reference data and linked fixed-income entries become informational. To keep holdings calculations, edit their prices/shares instead; those edits are recorded automatically.':'Applying this balance replaces the account starting value and records the observation. It does not create a contribution, withdrawal or taxable gain.'}</p><p class="help full">The as-of date labels history. It does not advance the plan start year or household ages. Older observations can be saved as history only. Multiple observations on one date are retained.</p>`;
 $('editor-fields').innerHTML=$('editor-fields').innerHTML.replaceAll('field-','balance-field-');
 $('balance-field-date').required=true;$('balance-field-date').max=localDate();$('editor').showModal();
}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.balanceUpdate)openBalanceUpdate(b.dataset.balanceUpdate);if(b.dataset.balanceHistory)run(async()=>{historyAccountId=b.dataset.balanceHistory;view='history';render();});});
document.addEventListener('change',e=>{if(e.target.id==='history-account'){historyAccountId=e.target.value;render();}});
